import subprocess
import time
from builtins import range
from taf.ul.trs_e2e_fw.lib.utils.decorators import check_rat
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.global_vars import global_vars
from taf.ul.trs_e2e_fw.lib.oam.exceptions import PingTestFailedException
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_vdu.base import BaseClass
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_vdu.cell_operations import CellOperations
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_vdu.exceptions import UnsuccessfulStatus
import traceback

logger = BackgroundLogger.Instance()


class Reset(BaseClass):
    """
    Reset
    """

    def __init__(self):
        super(Reset, self).__init__()

    @check_rat
    def reset(self, **kwargs):
        """
        Reset
        """
        operation = kwargs.get("operation", "''")
        # alias = kwargs.get("alias", "default")

        kwargs = {key: value for key, value in list(kwargs.items()) if key not in ["operation"]}
        logger.debug("Performing operation  {}...".format(operation.upper().replace("_", " ")))
        try:
            getattr(self, "_{}".format(operation.lower()))(**kwargs)
        except Exception as e:
            raise Exception("Operation {} not supported".format(operation))

    def _reset_bts(self, **kwargs):
        self.reset_bts(**kwargs)

    def reset_bts(self, **kwargs):
        """ Resets BTS
            :param verify_bts: Boolean. to check if BTS status should be onAir or not
            :param req_rat: which RATs status to be checked.
            :param wait_for: Time to wait(seconds) before checking for status after reset
            :param alias: Name of execution context
        """
        """
        Trigger VDU reset operation

        :param kwargs
        (str) connection: (optional) Unique identifier for a certain connections.
        (str) alias: (optional) Name of the execution context
        (int) timeout: (optional) Timeout for the operation
        (bool) verify_bts: (optional) True if bts status to be verified after reset
        (bool) should_be_onair: (optional) True if BTS should be onair, else False

        :returns: It returns dict containing information about status, id, error_message

        """
        alias = kwargs.get("alias", 'default')
        timeout = kwargs.get("timeout", 300)
        verify_bts = kwargs.get("verify_bts", False)
        req_rat = kwargs.pop("rat", 'all')
        should_be_onair = kwargs.pop("should_be_onair", True)
        wait_for = kwargs.pop("wait_for", 300)
        result_dict = self.factory.vdu_oam.reset_vdu(vdu_connection=alias, use_m2m=False)
        logger.debug("################## vdu reset called {}".format(result_dict))
        output = self._verify_status(result_dict, "Successful")
        if not output and result_dict["status"].lower() == "failed":
            raise UnsuccessfulStatus("Reset VDU unsuccessful.\nResponse status is : {}.\nResult dict is:{}".format(
                result_dict["status"], result_dict))
        if result_dict["status"].lower() == 'ongoing':
            time.sleep(float(timeout))
        if verify_bts:
            retry = 10
            while retry != 0:
                try:
                    result_dict = self.factory.vdu_oam.get_vdu_state_data(vdu_connection=alias, use_m2m=False)
                    if result_dict['operational_state'].lower() == 'enabled' or result_dict['operational_state'].lower() == 'configured':
                        return
                    time.sleep(30)
                except Exception as e:
                    logger.warn("Failed while verifying vdu state after reset. Make sure vdu is reachable. {}".format(e))
                    retry -= 1
            if should_be_onair:
                logger.debug("Checking if VDU is onAir")
                CellOperations().verify_bts_status(req_rat=req_rat, should_be_onair=should_be_onair,
                                                   wait_for=wait_for, alias=alias)

    def _reset_rannic(self, **kwargs):
        """
        Trigger VDU RANNIC reset operation

        :param kwargs
        (str) alias: Name of the execution context
        (int) timeout: (optional) Timeout for the operation
        (str) rannic_r_dn: ranic r dn,like MRBTS-10778/EQM_R-1/APEQM_R-1/RNICMOD_R-1

        :returns: dict including id,status of result.
        """

        rannic_r_dn = kwargs["rannic_dn"]
        alias = kwargs.get("alias", 'default')
        timeout = kwargs.get("timeout", 30)
        return self.factory.vdu_oam.reset_rannic(rannic_r_dn=rannic_r_dn, timeout=timeout, vdu_connection=alias)

    def _reset_rmods(self, **kwargs):
        """
        Trigger VDU RMODS reset operation

        :param kwargs
        (str) alias: Name of the execution context
        (int) timeout: (optional) Timeout for the operation
        (list(str)) rmods_list: list of runtime RMOD IDs, for example: ['123', '345']
        (str) reset_reason: (optional) the reset reason, default value is 'user'
        (bool) wait_for_completion: (optional) If set to True, the keyword will wait for the operation to complete.
        (int) graceful_cell_shutdown: (optional) if True cells will be shut gracefully, default value is False
        :returns: dict including id,status of result.
        """

        rmods_list = kwargs["rmods_list"]
        reset_reason = kwargs.get("reset_reason", 'default')
        graceful_cell_shutdown = kwargs.get("graceful_cell_shutdown", False)
        wait_for_completion = kwargs.get("wait_for_completion", False)
        alias = kwargs.get("alias", 'default')
        timeout = kwargs.get("timeout", 30)
        return self.factory.vdu_oam.reset_rmods(rmods_list=rmods_list, reset_reason=reset_reason,
                                                graceful_cell_shutdown=graceful_cell_shutdown, wait_for_completion=wait_for_completion,
                                                timeout=timeout, vdu_connection=alias)